fn parse(path: &str) -> Result<(u32, u32, u32, Vec<u32>), String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("read {path}: {e}"))?;
    let mut it = text.split_ascii_whitespace().map(|t| t.parse::<u32>());
    let mut next = || -> Result<u32, String> {
        it.next()
            .ok_or_else(|| "unexpected end of input".to_string())?
            .map_err(|e| format!("bad number: {e}"))
    };
    let w = next()?;
    let h = next()?;
    let steps = next()?;
    if w == 0 || h == 0 {
        return Err("empty grid".into());
    }
    let n = w as usize * h as usize;
    let mut cells = Vec::with_capacity(n);
    for _ in 0..n {
        cells.push(next()?);
    }
    Ok((w, h, steps, cells))
}

fn run_gpu(w: u32, h: u32, steps: u32, cells: &[u32]) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::default());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        force_fallback_adapter: false,
        compatible_surface: None,
    }))
    .map_err(|e| format!("no adapter: {e}"))?;
    let (device, queue) =
        pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
            .map_err(|e| format!("no device: {e}"))?;

    let size = (cells.len() * 4) as u64;
    let storage = wgpu::BufferUsages::STORAGE
        | wgpu::BufferUsages::COPY_SRC
        | wgpu::BufferUsages::COPY_DST;
    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("a"),
        contents: bytemuck::cast_slice(cells),
        usage: storage,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("b"),
        size,
        usage: storage,
        mapped_at_creation: false,
    });
    let dims = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: bytemuck::cast_slice(&[w, h, 0u32, 0u32]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let bind = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: dims.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: src.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: dst.as_entire_binding() },
            ],
        })
    };
    let a_to_b = bind(&buf_a, &buf_b);
    let b_to_a = bind(&buf_b, &buf_a);

    let mut enc = device.create_command_encoder(&Default::default());
    // Dispatches in one pass are ordered with respect to storage writes.
    for step in 0..steps {
        let mut pass = enc.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, if step % 2 == 0 { &a_to_b } else { &b_to_a }, &[]);
        pass.dispatch_workgroups(w.div_ceil(16), h.div_ceil(16), 1);
    }
    let result = if steps % 2 == 0 { &buf_a } else { &buf_b };
    enc.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit(Some(enc.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::Wait)
        .map_err(|e| format!("poll: {e:?}"))?;
    rx.recv()
        .map_err(|e| e.to_string())?
        .map_err(|e| format!("map: {e}"))?;
    let out = bytemuck::cast_slice::<u8, u32>(&slice.get_mapped_range()).to_vec();
    Ok(out)
}

fn main() {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu-heat <input-file>");
        std::process::exit(2);
    };
    let result = parse(&path).and_then(|(w, h, steps, cells)| {
        let out = run_gpu(w, h, steps, &cells)?;
        Ok((w, out))
    });
    let (w, out) = match result {
        Ok(v) => v,
        Err(e) => {
            eprintln!("error: {e}");
            std::process::exit(1);
        }
    };
    let mut text = String::new();
    for row in out.chunks(w as usize) {
        let line: Vec<String> = row.iter().map(u32::to_string).collect();
        text.push_str(&line.join(" "));
        text.push('\n');
    }
    let sum: u64 = out.iter().map(|&v| u64::from(v)).sum();
    text.push_str(&format!("SUM {sum}\n"));
    let mut stdout = std::io::stdout().lock();
    let _ = stdout.write_all(text.as_bytes());
}
